#include "tigersheets/biff.hpp"
#include "tigersheets/ooxml.hpp"
#include <xls.h>
#include <filesystem>
#include <fstream>
#include <functional>
#include <iostream>
#include <memory>
#include <stdexcept>
#include <unistd.h>
using namespace tigersheets;
namespace {
void require(bool yes,const char* message){if(!yes)throw std::runtime_error(message);}
unsigned word(std::string_view bytes,std::size_t at){require(at+2<=bytes.size(),"native BIFF record bounds");return static_cast<unsigned char>(bytes[at])|(static_cast<unsigned char>(bytes[at+1])<<8);}
void records(std::string_view stream,std::size_t offset,const std::function<void(unsigned,std::string_view)>& visit){while(offset+4<=stream.size()){const auto id=word(stream,offset),size=word(stream,offset+2);offset+=4;require(size<=stream.size()-offset,"native BIFF record length");visit(id,stream.substr(offset,size));offset+=size;if(id==10)return;}throw std::runtime_error("native BIFF EOF");}
std::string bytes(const std::string& path){std::ifstream input(path,std::ios::binary);return {std::istreambuf_iterator<char>(input),{}};}
void inspect(const std::string& path,int active){const auto file=bytes(path);xls::xls_error_t error=xls::LIBXLS_OK;std::unique_ptr<xls::xlsWorkBook,decltype(&xls::xls_close_WB)> native(xls::xls_open_buffer(reinterpret_cast<const unsigned char*>(file.data()),file.size(),"UTF-8",&error),xls::xls_close_WB);require(native!=nullptr,"independent CFB stream opens");std::string stream(native->olestr->size,'\0');require(xls::ole2_seek(native->olestr,0)==0&&xls::ole2_read(stream.data(),1,stream.size(),native->olestr)==static_cast<ssize_t>(stream.size()),"read native Workbook stream");bool tab=false;records(stream,0,[&](unsigned id,std::string_view data){if(id==0x3d){require(word(data,10)==static_cast<unsigned>(active),"WINDOW1 selected tab uses native itabCur, not fixed zero");require(word(data,14)==1,"exactly one native sheet tab is selected");tab=true;}});require(tab,"native WINDOW1 exists");for(unsigned index=0;index<native->sheets.count;++index){bool window=false,selection=false,scl=false;records(stream,native->sheets.sheet[index].filepos,[&](unsigned id,std::string_view data){if(id==0x23e){require(((word(data,0)&0x600)==0x600)==(index==static_cast<unsigned>(active)),"WINDOW2 marks only the active tab selected and displayed");if(index==static_cast<unsigned>(active))require(word(data,2)==36&&word(data,4)==1&&word(data,12)==125,"WINDOW2 retains top B37 and normal zoom125 in specified native fields");window=true;}else if(id==0x1d){if(index==static_cast<unsigned>(active)){require(static_cast<unsigned char>(data[0])==3&&word(data,1)==50&&word(data,3)==4&&word(data,5)==0&&word(data,7)==1,"SELECTION retains pane, active E51, active range index and count");require(word(data,9)==50&&word(data,11)==52&&static_cast<unsigned char>(data[13])==4&&static_cast<unsigned char>(data[14])==6,"native RefU retains E51:G53 inclusive bounds");}selection=true;}else if(id==0xa0){if(index==static_cast<unsigned>(active))require(word(data,0)*100==word(data,2)*125,"native SCL retains zoom fraction125 percent");scl=true;}else if(id==0x7d&&index==static_cast<unsigned>(active)&&word(data,0)==4)require((word(data,8)&4)!=0,"native COLINFO retains AutoFit bestFit bit2");});require(window&&selection&&scl,"each worksheet has native window, selection and zoom records");}}
Json fixture(){Json book={{"revision",0},{"activeSheetIndex",2},{"sheets",Json::array()}};for(int index=0;index<3;++index)book["sheets"].push_back({{"id",std::to_string(index)},{"name","Sheet"+std::to_string(index+1)},{"cells",Json::array()},{"nativeView",{{"activeCell","B2"},{"selection","B2:D4"},{"topLeftCell","A1"},{"zoomScale",100}}}});book["sheets"][0]["nativeView"]["selection"]="A1 B2:D4";book["sheets"][1]["nativeView"]={{"activeCell","IV65536"},{"selection","A1:XFD1048576"},{"topLeftCell","A1"},{"zoomScale",75}};book["sheets"][2]["nativeView"]={{"activeCell","E51"},{"selection","E51:G53"},{"topLeftCell","B37"},{"zoomScale",125}};book["sheets"][2]["columnLayout"]=Json::array({{{"index",5},{"size",18.5},{"bestFit",true}}});return book;}
void roundtrip(const std::string& path,bool source){auto book=source?readWorkbook(std::string(TIGERSHEETS_SOURCE_DIR)+"/tests/fixtures/biff/financial-source.xls").workbook:fixture();const int active=source?36:2;book["activeSheetIndex"]=active;book["sheets"][active]["nativeView"]={{"activeCell","E51"},{"selection","E51:G53"},{"topLeftCell","B37"},{"zoomScale",125}};book["sheets"][active]["columnLayout"]=Json::array({{{"index",5},{"size",18.5},{"bestFit",true}}});writeBiffWorkbook(path,book);inspect(path,active);const auto reopened=readWorkbook(path).workbook;require(reopened.value("activeSheetIndex",-1)==active,"native BIFF active worksheet survives import");require(reopened.at("sheets")[active].at("nativeView")==book.at("sheets")[active].at("nativeView"),"native BIFF active cell, range, scroll and zoom roundtrip");bool bestFit=false;for(const auto& entry:reopened.at("sheets")[active].at("columnLayout"))if(entry.at("index")==5)bestFit=entry.value("bestFit",false);require(bestFit,"native AutoFit provenance survives import");if(!source){require(reopened.at("sheets")[1].at("nativeView").at("selection")=="A1:IV65536","only a full modern worksheet selection is clamped to legacy worksheet bounds");require(reopened.at("sheets")[0].at("nativeView")==book.at("sheets")[0].at("nativeView"),"multiple selected rectangles preserve their active cell and native range membership");}if(const auto* retained=std::getenv("TIGERSHEETS_BIFF_VIEW_CAPTURE"))std::filesystem::copy_file(path,retained,std::filesystem::copy_options::overwrite_existing);}
void bestFit(const std::string& path){auto book=fixture();writeBiffWorkbook(path,book);const auto reopened=readWorkbook(path).workbook;bool found=false;for(const auto& entry:reopened.at("sheets")[2].at("columnLayout"))if(entry.at("index")==5)found=entry.value("bestFit",false);require(found,"native BIFF saves and imports AutoFit bestFit provenance instead of dropping it");}
void bounds(const std::string& path){auto book=fixture();writeBiffWorkbook(path,book);const auto original=bytes(path);for(const auto& change:Json::array({Json{{"activeCell","A65537"}},Json{{"topLeftCell","IW1"}},Json{{"selection","A1:A65537"}},Json{{"selection","IV1:IW2"}},Json{{"zoomScale",401}}})){auto bad=book;bad["sheets"][2]["nativeView"].update(change);bool refused=false;try{writeBiffWorkbook(path,bad);}catch(const std::runtime_error&){refused=true;}require(refused&&bytes(path)==original,"unrepresentable finite native view refuses atomically before replacing the original XLS");}}
}
int main(int argc,char** argv){const auto path=(std::filesystem::temp_directory_path()/("tigersheets-biff-view-"+std::to_string(getpid())+".xls")).string();try{const std::string mode=argc>1?argv[1]:"";if(mode=="bounds")bounds(path);else if(mode=="bestfit")bestFit(path);else roundtrip(path,mode=="source");std::filesystem::remove(path);std::cout<<"Native BIFF view persistence passed\n";}catch(const std::exception& error){std::filesystem::remove(path);std::cerr<<"FAILED: "<<error.what()<<'\n';return 1;}}
